import {launchPi} from '/tmp/ui-paced-fixture.ts';
import {writeFile,readFile,readdir} from 'node:fs/promises';
import {join} from 'node:path';
const file='/tmp/ui-paced-performance.jsonl';
await writeFile(file,'');
for (const [sample,enabled] of [false,true,true,false,false,true].entries()) {
 const host=await launchPi(JSON.stringify({ui:{enabled},rtk:{rewrite:false,ansi:false}}),'/tmp/ui-paced-observer.ts','ui');
 console.log(JSON.stringify({phase:'start',sample,enabled}));
 try {
  await writeFile(join(host.agent,'settings.json'),JSON.stringify({compaction:{enabled:false},hideThinkingBlock:false}));
  await host.reload();await host.terminal.resize({cols:100,rows:36});
  await writeFile(join(host.directory,'source.ts'),Array.from({length:300},(_,i)=>`export const value${i} = ${i};`).join('\n'));
  for(let i=0;i<8;i++)await host.sequence(Array.from({length:8},()=>({name:'read',parameters:'{"path":"source.ts"}'})));
  async function resources(label:string) {
   await host.command(`/measure-resources ${label}`);
   await host.terminal.screen.waitUntil(async()=>{try{return JSON.parse(await readFile(join(host.directory,'resources.json'),'utf8')).label===label;}catch{return false;}},{timeoutMs:5000});
   return JSON.parse(await readFile(join(host.directory,'resources.json'),'utf8'));
  }
  await host.terminal.screen.waitUntil(async()=>{try{return await readFile(join(host.directory,'settled-count'),'utf8')==='8';}catch{return false;}},{timeoutMs:5000});
  const initial=await resources('stream-start');
  const thought=Array.from({length:200},(_,i)=>`THINK_${String(i).padStart(3,'0')} Inspecting retained row ${i}, comparing values and boundary cases.`).join('\n');
  const answer=Array.from({length:400},(_,i)=>`${i%3===0?'- ':''}TEXT_${String(i).padStart(3,'0')} Verified row ${i}: **expected value** and `+'`source.ts` remain unchanged.').join('\n');
  const begun=performance.now();await host.startResponse(answer,thought);
  const observations=[];
  for (const [phase,prefix,points] of [['thinking','THINK',[0,49,99,199]],['text','TEXT',[0,99,199,299,399]]] as const) {
   for(const index of points){
    const marker=`${prefix}_${String(index).padStart(3,'0')}`;
    await host.terminal.screen.waitForText(marker,{timeoutMs:15000});
    const seen=performance.now();const emitted=host.emissions.find(x=>x.phase===phase&&x.index===index);
    if(!emitted)throw new Error('Visible marker preceded emission');
    observations.push({phase,index,delayMs:seen-emitted.time});
    if(index===99){
     const draft=`DRAFT_${phase.toUpperCase()}_99`;
     const typed=performance.now();await host.terminal.keyboard.type(draft);
     await host.terminal.screen.waitForText(draft,{timeoutMs:10000});
     observations.push({phase,index,typingMs:performance.now()-typed});await host.terminal.keyboard.press('Control+U');
     await host.terminal.screen.waitUntil(snapshot=>!snapshot.text.includes(draft),{timeoutMs:5000});
    }
   }
  }
  await host.terminal.screen.waitUntil(()=>host.streamComplete(),{timeoutMs:5000});
  await host.terminal.screen.waitUntil(async()=>await readFile(join(host.directory,'settled-count'),'utf8')==='9',{timeoutMs:5000});
  const elapsedMs=performance.now()-begun;
  const final=await resources('stream-end');
  const sessions=await readdir(join(host.directory,'sessions'),{recursive:true});
  const saved=sessions.find(name=>name.endsWith('.jsonl'));if(!saved)throw new Error('No session');
  const entries=(await readFile(join(host.directory,'sessions',saved),'utf8')).trim().split('\n').map(line=>JSON.parse(line));
  const assistant=entries.findLast(e=>e.type==='message'&&e.message.role==='assistant').message;
  if(assistant.content.filter(b=>b.type==='text').map(b=>b.text).join('')!==answer)throw new Error('Final answer changed');
  if(assistant.content.filter(b=>b.type==='thinking').map(b=>b.thinking).join('')!==thought)throw new Error('Final thinking changed');
  const result={sample,enabled,elapsedMs,observations,emissions:host.emissions,initial,final};
  await writeFile(file,JSON.stringify(result)+'\n',{flag:'a'});console.log(JSON.stringify({phase:'complete',sample,enabled,elapsedMs,observations}));
 }finally{await host.close();}
}

