import type {ExtensionAPI} from '<WORKTREE>/node_modules/@earendil-works/pi-coding-agent';
import {Effect} from '<WORKTREE>/node_modules/effect/dist/index.js';
import {writeFile} from 'node:fs/promises';
import {join} from 'node:path';

export default function (pi: ExtensionAPI) {
  let settled = 0;
  pi.on('agent_settled', async (_event, ctx) => {
    settled++;
    await Effect.runPromise(Effect.tryPromise({
      try: () => writeFile(join(ctx.cwd, 'settled-count'), String(settled)),
      catch: cause => new Error('Could not record settled state', {cause}),
    }));
  });
  pi.registerCommand('measure-resources', {
    description: 'Isolated UI performance observation',
    handler: async (label, ctx) => {
      const data = {
        label: label.trim(),
        pid: process.pid,
        bun: Bun.version,
        columns: process.stdout.columns, rows: process.stdout.rows,
        cpu: process.cpuUsage(),
        memory: process.memoryUsage(),
      };
      await Effect.runPromise(Effect.tryPromise({
        try: () => writeFile(join(ctx.cwd, 'resources.json'), JSON.stringify(data)),
        catch: cause => new Error('Resource observation failed', {cause}),
      }));
    },
  });
}
